"""Summarize read-only CLDR diagnoses without changing frozen admission policy."""
from pathlib import Path
import json
C=Path(__file__).resolve().parent;E=C/'evidence'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
probes=load(E/'probe-receipts.json');controls=load(E/'control-receipts.json');initial=load(E/'initial-controls/control-receipts.json');normal=load(E/'normal-case-receipts.json')
assert len(probes)==len(normal)==6 and len(controls)==len(initial)==22
for r in probes+controls+initial+normal:assert r['exitCode']==0 and not r['timeout']
assert sum(r['result']['kind']=='Passed' for r in probes)==4 and sum(r['result']['kind']=='Failed' for r in probes)==2
assert {r['name'] for r in probes if r['result']['kind']=='Failed'}=={'qt4-format-integer-076','qt4-format-integer-077'}
for r in probes:
 if r['result']['kind']=='Failed':assert 'FODF1310' in r['result']['message']
assert sum(r['result']['kind']=='Passed' for r in controls)==14 and sum(r['result']['kind']=='Failed' for r in controls)==8
expected={s+'-control-'+name for s in ['qt3','qt4'] for name in ['cardinal-named','ordinal-named-s','ordinal-named-r','ordinal-named-n']}
assert {r['name'] for r in controls if r['result']['kind']=='Failed'}==expected
assert sum(r['result']['kind']=='Passed' for r in initial)==8 and sum(r['result']['kind']=='Failed' for r in initial)==14
assert all(r['totals']==([1,1,0,0] if r['suite']=='qt3' else [1,0,0,1]) for r in normal)
result=dict(date='2026-10-27',slice='K04-C05',status='Read-only review complete;implementation and qt4 feature admission remain open',sourceBase=load(E/'REVIEW-PIN.json')['sourceBase'],summary=dict(originalCases=6,originalQt3Passed=2,originalQt4PassedDirect=2,originalQt4FailedDirect=2,normalQt3Passed=2,normalQt4Skipped=4,finalModifierControlProcesses=22,finalModifierControlsPassed=14,finalModifierControlsFailed=8,initialCalibrationProcesses=22,initialExpectationMistakes=6,smallWatchdogProcesses=56,timeouts=0,sourceChanged=False,baselineChanged=False,inheritedSolutionPassed=22007,inheritedNormalQt3=[31161,0,660],inheritedQt4Gated=[8438,0,1892],candidateVersion='1.26.11',publishedVersion='1.26.3'),findings=[dict(id='K04-CLDR-01',observation='ParseModifier accepts plain c and o(...), but rejects named cardinal c(...), yielding FODF1310 in original qt4 cases076/077.',source='FormatIntegerEngine.ParseModifier',scope='Original assertion failure;fix requires immutable specification/CLDR pins before semantic changes.'),dict(id='K04-CLDR-02',observation='GermanToOrdinalWords maps every percent-prefixed variation to ending e. Named s/r/n controls yield Erste instead of Erstes/Erster/Ersten;explicit -es/-er/-en controls pass in both profiles.',source='FormatIntegerEngine.GermanToOrdinalWords',scope='Derived mechanism diagnosis, not a new conformance certification.'),dict(id='K04-CLDR-CALIBRATION',observation='Initial explicit-ending controls incorrectly used -s/-r/-n;these are literal endings and produced Ersts/Erstr/Erstn. Corrected controls use -es/-er/-en. All initial inputs/results retained separately.',scope='Six initial expected-value mistakes are not engine defects.')],retainedOriginalFailures=[r for r in probes if r['result']['kind']=='Failed'],retainedModifierFailures=[r for r in controls if r['result']['kind']=='Failed'],next='Pin immutable F&O and CLDR variation semantics;implement bounded named-cardinal parsing and known German ordinal endings;preserve malformed pictures and fallback behavior;pass original cases/unit regressions/full gates before considering qt4 CLDR admission.',limits=['No source,harness,fixture,assertion,version,admission or baseline change','No fresh full solution/conformance gate run;source-identical accepted results inherited explicitly','QT3 legacy admission is not complete CLDR support','Bosak.Schema owns staged XSD1.1;REQ-126 remains Complete','No release or upstream contribution'])
